import math
import numpy as np


def r_1(x: float) -> float:
    """Complement input transformation: x -> 1 - x."""
    return float(1.0 - x)


def R_1(y_orig: float, y_new: float) -> bool:
    """Output relation: det(A(x)) + det(A(1-x)) = 15.

    We check if the sum of the original and transformed outputs is 15
    within a reasonable floating-point tolerance.
    """
    if not (math.isfinite(y_orig) and math.isfinite(y_new)):
        return False
    return math.isclose(y_orig + y_new, 15.0, rel_tol=1e-9, abs_tol=1e-9)
